float vrchDissolveHash(vec2 point) {
  return fract(sin(dot(point, vec2(17.17, 113.51))) * 43758.5453);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec4 image = vrchSampleSource0(uv);
  float pathPhase = iTime * (0.32 + uParam_motion * 0.85);
  float motionWave = sin(pathPhase);
  float angle = (uParam_angle + motionWave * uParam_motion * 0.1) * 6.28318530718;
  vec2 direction = vec2(cos(angle), sin(angle));
  float breathing = 0.9 + 0.1 * sin(pathPhase * 0.73 + 1.1);
  float trailLength = uParam_length * breathing;
  float grain = vrchDissolveHash(floor(fragCoord / max(uParam_grain, 1.0)));
  float dissolveField = smoothstep(uParam_dissolve - 0.12, uParam_dissolve + 0.12, grain);
  float signedGrain = grain * 2.0 - 1.0;
  float pixelScale = max(min(iResolution.x, iResolution.y), 1.0);
  vec2 grainOffset = direction * signedGrain * trailLength * (0.2 + dissolveField * 0.55) / pixelScale;
  vec2 displacedUv = clamp(uv - grainOffset, vec2(0.0), vec2(1.0));
  vec4 displaced = vrchSampleSource0(displacedUv);
  vec2 stepUv = direction * trailLength * 2.4 / pixelScale;
  vec4 trail = vec4(0.0);
  float trailWeight = 0.0;
  for (int i = 0; i < 7; i++) {
    float fi = float(i) / 6.0;
    float weight = 1.0 - fi * 0.55;
    trail += vrchSampleSource0(clamp(displacedUv - stepUv * fi, vec2(0.0), vec2(1.0))) * weight;
    trailWeight += weight;
  }
  trail /= max(trailWeight, 0.001);
  float blurWeight = uParam_blur_mix * (0.35 + dissolveField * 0.65);
  vec3 carriedSource = mix(displaced.rgb, trail.rgb, blurWeight);
  float treatment = 1.0 - pow(abs(1.0 - clamp(uParam_amount, 0.0, 1.0)), 2.0);
  vec3 color = mix(image.rgb, carriedSource, treatment);
  fragColor = vec4(color, image.a);
}
